document.querySelectorAll('[data-embed]').forEach(button=>button.addEventListener('click',()=>{const src=new URL(button.dataset.src);if(!['www.opentable.com','www.google.com'].includes(src.hostname))return;const frame=document.createElement('iframe');frame.src=src.href;frame.title=button.dataset.embed==='map'?'Flavors From Afar location map':'Reserve with OpenTable';frame.loading='lazy';frame.width='100%';frame.height='480';frame.referrerPolicy='strict-origin-when-cross-origin';button.after(frame);button.hidden=true;window.dispatchEvent(new CustomEvent('ffa-track',{detail:{event:button.dataset.embed==='map'?'map_open':'reservation_widget_open',placement:location.pathname}}))}));
